def lease_occupancy(limit, requests):
    if limit < 0:
        raise ValueError("limit")
    accepted, result = [], []
    for req in requests:
        start, end, seats = req[0], req[1], req[2]
        if end <= start or seats < 0:
            raise ValueError("lease")
        accepted = [pr for pr in accepted if pr[1] > start]
        can_take = sum(pr[2] for pr in accepted) + seats <= limit
        if can_take:
            accepted.append([start, end, seats])
        result.append(can_take)
    return result

