        raise ValueError("invalid band")
    acc_weight = 0
    matched = 0
    for entry in spans:
        left, right, weight = entry[0], entry[1], entry[2]
        if right > left:
            lo_pos = max(low, left)
            hi_pos = min(high, right)
            overlap = hi_pos - lo_pos
            if overlap > 0:
                acc_weight += overlap * weight
                matched += 1
    return [acc_weight, matched]

