def atomic_kit_builds(inventory, kits):
    pool = dict(inventory)
    for qty in pool.values():
        if qty < 0:
            raise ValueError("stock")
    flags = []
    for kit in kits:
        trial = dict(pool)
        ok_flag = True
        for part_name in kit:
            rem = trial.get(part_name, 0)
            if rem <= 0:
                ok_flag = False
                break
            trial[part_name] = rem - 1
