def panel_consensus(panels, threshold):
    if threshold <= 0:
        raise ValueError("invalid threshold")
    tally = {}
    for members in panels:
        for tag in {item for item in members if item != ""}:
            tally[tag] = tally.get(tag, 0) + 1
