def lru_pin_evictions(capacity, actions):
    if capacity < 1:
        raise ValueError("cap")
    order, pinned, out = [], set(), []
    for op, key in actions:
        if op == "put":
            if key in order:
                order.remove(key)
            elif len(order) == capacity:
                vic = next(( ky for ky in order if ky not in pinned ), None)
                if vic is None:
                    raise ValueError("pin")
                order.remove(vic)
                out.append(vic)
            order.append(key)
        elif op == "pin" and key in order:
            pinned.add(key)
        elif op == "unpin":
            pinned.discard(key)
        elif op != "pin":
            raise ValueError("op")
    return [out, order]

def lru_pin_evictions(capacity, actions):
    if capacity <= 0:
        raise ValueError("cap")
    entries, evicted = [], []
    for act in actions:
        op_name, key = act[0], act[1]
        pos = next((idx for idx, pr in enumerate(entries) if pr[0] == key), -1)
        if op_name == "put":
            if pos >= 0:
                was_pin = entries.pop(pos)[1]
                entries.append([key, was_pin])
            else:
                if len(entries) == capacity:
                    ev_i = next((idx for idx, pr in enumerate(entries) if not pr[1]), -1)
                    if ev_i < 0:
                        raise ValueError("pinned")
                    evicted.append(entries.pop(ev_i)[0])
                entries.append([key, False])
        elif op_name == "pin" and pos >= 0:
            entries[pos][1] = True
        elif op_name == "unpin" and pos >= 0:
            entries[pos][1] = False
        elif op_name not in ("pin", "unpin"):
            raise ValueError("op")
    return [evicted, [pr[0] for pr in entries]]

