def tiered_seat_assign(candidates, group_caps):
    if any(lim < 0 for lim in group_caps.values()):
        raise ValueError("cap")
    caps, chosen = dict(group_caps), set()
    for idx in sorted(range(len(candidates)), key=lambda pos: (-candidates[pos][2], pos)):
        grp = candidates[idx][1]
        if caps.get(grp, 0) > 0:
            caps[grp] -= 1
            chosen.add(idx)
    return [candidates[idx][0] for idx in range(len(candidates)) if idx in chosen]

def tiered_seat_assign(candidates, group_caps):
    rem_caps = dict(group_caps)
    for lim in rem_caps.values():
        if lim < 0:
            raise ValueError("negative cap")
    indexed = [[-row[2], pos, row[0], row[1]] for pos, row in enumerate(candidates)]
    indexed.sort()
    accepted_pos = []
    for item in indexed:
        grp = item[3]
        avail = rem_caps.get(grp, 0)
        if avail > 0:
            rem_caps[grp] = avail - 1
            accepted_pos.append(item[1])
    accepted_pos.sort()
    return [candidates[pos][0] for pos in accepted_pos]

