def berth_allocations(tonnage_cap, vessels):
    if tonnage_cap < 0:
        raise ValueError("negative cap")
    docked = []
    flags = []
    peak = 0
    for arrive, depart, tons in vessels:
        if depart <= arrive or tons < 0:
            raise ValueError("invalid vessel")
        docked = [entry for entry in docked if entry[1] > arrive]
        cur_tons = sum(entry[2] for entry in docked)
        if cur_tons + tons <= tonnage_cap:
            docked.append([arrive, depart, tons])
            cur_tons += tons
            if cur_tons > peak:
                peak = cur_tons
            flags.append(True)
        else:
            flags.append(False)
    return [flags, peak]

def berth_allocations(tonnage_cap, vessels):
    if tonnage_cap < 0:
        raise ValueError("negative cap")
    live = []
    decisions = []
    max_load = 0
    for item in vessels:
        arrive, depart, tons = item[0], item[1], item[2]
        if depart <= arrive or tons < 0:
            raise ValueError("invalid vessel")
        kept = []
        load = 0
        for ship in live:
            if ship[1] > arrive:
                kept.append(ship)
                load += ship[2]
        live = kept
        ok_ship = load + tons <= tonnage_cap
        if ok_ship:
            live.append([arrive, depart, tons])
            if load + tons > max_load:
                max_load = load + tons
        decisions.append(ok_ship)
    return [decisions, max_load]

