def tariff_window_charge(open_hr, close_hr, bookings):
    width = close_hr - open_hr
    if width <= 0:
        raise ValueError("invalid window")
    diff = [0] * (width + 1)
    for item in bookings:
        start_hr, end_hr, rate = item[0], item[1], item[2]
        if end_hr > start_hr:
            lo_idx = max(0, start_hr - open_hr)
            hi_idx = min(width, end_hr - open_hr)
            if hi_idx > lo_idx:
                diff[lo_idx] += rate
                diff[hi_idx] -= rate
    out = []
    running = 0
    for idx in range(width):
        running += diff[idx]
        out.append(running)
    return out

