    marks = {}
    seen = set()
    out = []
    for row in readings:
        kind, sensor_id, value = row[0], row[1], row[2]
        if kind == "recal":
            seen.discard(sensor_id)
            marks.pop(sensor_id, None)
        elif kind == "sample":
            if sensor_id not in seen:
                seen.add(sensor_id)
                marks[sensor_id] = value
                out.append(0)
            else:
                prev = marks[sensor_id]
                if value > prev:
                    out.append(value - prev)
                    marks[sensor_id] = value
                else:
                    out.append(0)
        else:
            raise ValueError("unknown kind")
    return out

