def workqueue_promotions(limit, commands):
    if limit <= 0:
        raise ValueError("invalid limit")
    active = []
    evicted = []
    for item in commands:
        cmd, job = item[0], item[1]
        if cmd == "push":
            if job in active:
                active = [entry for entry in active if entry != job] + [job]
            else:
                if len(active) == limit:
                    evicted.append(active[0])
                    active = active[1:]
                active.append(job)
        elif cmd == "pop":
            if active:
                active = active[1:]
