def budgeted_grant_order(proposals, dept_budgets):
    rem = dict(dept_budgets)
    for amt in rem.values():
        if amt < 0:
            raise ValueError("negative budget")
    ranked = []
    for pos, row in enumerate(proposals):
        if row[3] < 0:
            raise ValueError("negative cost")
        ranked.append([-row[2], pos, row[0], row[1], row[3]])
    ranked.sort()
    picked_pos = []
    for entry in ranked:
        dept, cost = entry[3], entry[4]
        avail = rem.get(dept, 0)
        if cost <= avail:
            rem[dept] = avail - cost
            picked_pos.append(entry[1])
    picked_pos.sort()
    return [proposals[pos][0] for pos in picked_pos]

