def fsm_door_cycles(commands):
    table = {
        ("closed", "open"): ("open", 0),
        ("open", "close"): ("closed", 1),
        ("closed", "lock"): ("locked", 0),
        ("locked", "unlock"): ("closed", 0),
    }
    allowed = {"open", "close", "lock", "unlock"}
    cur = "closed"
    done = 0
    for cmd in commands:
        if cmd not in allowed:
            raise ValueError("unknown command")
        step = table.get((cur, cmd))
        if step is not None:
            cur, inc = step
            done += inc
    return [cur, done]

