def frame_byte_decoder(stream):
    for byte_val in stream:
        if byte_val < 0 or byte_val > 255:
            raise ValueError("byte out of range")
    idx = 0
    total = len(stream)
    out = []
    while idx < total:
        cur = stream[idx]
        if cur == 254:
            if idx + 1 >= total:
                raise ValueError("truncated escape")
            out.append(stream[idx + 1] ^ 32)
            idx += 2
        elif cur == 255:
            if idx + 2 >= total:
                raise ValueError("truncated pair")
            out.append((stream[idx + 1] + stream[idx + 2]) % 256)
            idx += 3
        else:
            out.append(cur)
            idx += 1
    return out

