    delay = base_delay
    successes = 0
    waited = 0
    for cur in outcomes:
        if cur not in allowed:
            raise ValueError("unknown outcome")
        if cur == "fatal":
            break
        if cur == "ok":
            successes += 1
            delay = base_delay
