    for item in values[:width]:
        counts[item] = counts.get(item, 0) + 1
    out = [sum(1 for freq in counts.values() if freq == 1)]
    for pos in range(width, len(values)):
        entering = values[pos]
        leaving = values[pos - width]
        counts[entering] = counts.get(entering, 0) + 1
        counts[leaving] -= 1
        if counts[leaving] == 0:
