def min_paren_repairs(symbols):
    openers = []
    inserted_openers = 0
    for tok in symbols:
        if tok == "(" or tok == "[":
            openers.append(tok)
        elif tok == ")":
            if openers and openers[-1] == "(":
                openers.pop()
            else:
                inserted_openers += 1
        elif tok == "]":
            if openers and openers[-1] == "[":
