def callstack_exclusive_time(trace):
    frames = []
    totals = {}
    last_time = None
    for row in trace:
        kind, func_name, cur_ts = row[0], row[1], row[2]
        if (kind != "enter" and kind != "exit") or func_name == "" or cur_ts < 0:
            raise ValueError("invalid event")
        if last_time is not None and cur_ts < last_time:
            raise ValueError("non-monotone timestamp")
        if kind == "enter":
            frames.append([func_name, cur_ts, 0])
            totals.setdefault(func_name, 0)
        else:
            if not frames or frames[-1][0] != func_name:
                raise ValueError("mismatched exit")
            popped = frames.pop()
            span = cur_ts - popped[1]
            totals[func_name] += span - popped[2]
            if frames:
                frames[-1][2] += span
        last_time = cur_ts
    if frames:
        raise ValueError("unclosed call")
    return [[name, totals[name]] for name in sorted(totals)]

