def ordered_union_versions(streams):
    for stream in streams:
        for entry in stream:
            if entry[0] == "":
                raise ValueError("empty pkg")
    seen_pos = {}
    max_map = {}
    counter = 0
    for stream in streams:
        for entry in stream:
            pkg, ver = entry[0], entry[1]
            if ver >= 0:
                if pkg not in seen_pos:
                    seen_pos[pkg] = counter
                    counter += 1
                    max_map[pkg] = ver
                else:
                    max_map[pkg] = max(max_map[pkg], ver)
    ordered_pkgs = sorted(seen_pos, key=lambda name: seen_pos[name])
    return [[name, max_map[name]] for name in ordered_pkgs]

